from author import *
c=C('虚拟内存与页面置换')
S(c,'请求调页与缺页处理',[T('请求调页','页面不必在开始时全部装入内存'),T('缺页条件','访问合法，但所需页当前不在内存'),T('处理链','保存现场 → 调入页面 → 更新映射 → 重试')],[P('虚拟内存允许程序看到的地址空间，不必等于当前实际驻留的物理内存。请求调页在需要某页时才把它调入。访问合法但页面尚未驻留，就发生缺页异常；若访问本身越界或无权限，则不能简单靠调页解决。页表除了映射信息，还可能包含存在、修改、访问和保护等状态位。',[1,2],['合法但未驻留，才按缺页处理','非法地址不是随便调入就合法'],phase='fault',anchor='就发生缺页异常'),P('缺页后进入内核，必要时选择页框；若被换出的页已经修改，可能先写回，再读入所需页。涉及外存等待时，当前执行流可能阻塞，系统去运行别的任务。页面到位后更新页表等信息，恢复时重新执行引发缺页的指令。缺页不等于整个程序必须从第一行重跑，也不表示处理器全程只能空等。',[3],['脏页可能增加写回成本','恢复后重试发生缺页的指令'],phase='load',anchor='页面到位后更新页表')],['请求分页','缺页异常'],visual=G('page_fault'))
S(c,'FIFO与Belady异常',[T('FIFO规则','淘汰最早进入内存、仍驻留的页面'),T('命中时','通常不改变FIFO入内存顺序'),T('反常现象','FIFO增加页框后，缺页次数可能反而增加')],[P('先进先出看的是进入内存的时间。先用三页框访问七、零、一，三个页面依次装入；再访问二，淘汰最早装入的七。接着访问零命中，但FIFO队列不因此把零搬到最后。继续访问三时，该淘汰的仍是较早装入的零。把命中也当成重新入队，就把FIFO误写成了另一种策略。',[1,2],['FIFO按装入先后，不按最近访问','首次装入也计一次缺页'],phase='fifo',anchor='再访问二'),P('FIFO有一个常考现象，叫Belady异常：对某些访问序列，页框从三个增加到四个，缺页反而更多。这里的经典序列在三个页框时缺九次，四个页框时缺十次。它说明增加空间并不保证每种算法对每条序列都单调改善；不是说内存越大通常越差，也不能把这个结论扩展给所有置换算法。',[3],['Belady异常不是所有算法都有','必须比较同一条访问序列'],phase='belady',anchor='三个页框时缺九次')],['FIFO','Belady异常'],visual=G('replacement',algorithm='fifo'))
S(c,'LRU与最佳置换OPT',[T('LRU','淘汰最近最长时间没有被访问的页'),T('OPT','淘汰未来最晚再访问，或不再访问的页'),T('同一13次访问例','三页框：FIFO缺10，LRU缺9，OPT缺7')],[P('LRU看过去：哪个页最近最久没用，就优先淘汰哪个，因此命中也要更新最近使用次序。OPT看未来：哪个页下次使用最晚，或者以后不再使用，就选它。OPT需要预知后续访问，主要作为理论比较标准；不要把它说成通常可以直接预知真实程序未来行为的在线算法。',[1,2],['LRU看过去，OPT看未来','LRU命中要更新使用次序'],phase='lru',anchor='LRU看过去'),P('用图上的同一条十三次访问序列比较，初始三页框全空，FIFO缺十次，LRU缺九次，OPT缺七次。计数时每次先判断当前是否命中，只有未命中才算一次缺页；有空框先装入，没有空框再选择被淘汰页。不能只数发生替换的次数，而漏掉最开始填空框的几次缺页。',[3],['先判命中，再决定是否替换','缺页次数包含初次装入'],phase='opt',anchor='OPT缺七次')],['LRU','OPT'],visual=G('replacement',algorithm='lru'))
S(c,'时钟置换算法',[T('基本Clock','循环指针＋访问位，近似考虑近期使用'),T('访问位为1','清零并跳过，给第二次机会'),T('访问位为0','选为候选并按规则更新指针')],[P('基本时钟算法把页框排成环，指针依次检查访问位。访问位一表示近期被访问过，先清零并跳过；遇到零才选择替换。本例指针指向第一页，访问位依次一、零、一，先清第一页的位；此时还需继续扫描，不能立刻选择刚清零的第一页。',[1,2],['访问位不是脏位','指针位置也是题目状态的一部分'],phase='scan',anchor='先清第一页的位'),P('接着选择第二页，用新页替换它，把新页访问位置为一，指针移到下一页。改进型时钟还会参考修改位，尽量减少淘汰脏页带来的写回。访问位表示是否被用过，修改位表示是否被写过，含义不同。具体扫描轮次、清位时机和候选优先级要读题，不能只背一个零一组合就跳过完整过程。它与精确LRU不同，并不完整记录所有页面的时间顺序。',[3],['修改位影响写回代价','改进型扫描规则以题设为准'],phase='replace',anchor='接着选择第二页')],['Clock','改进Clock'],visual=G('clock'))
S(c,'缺页率与有效访问时间',[T('题设','不缺页100ns；缺页一次总耗时8ms'),T('缺页率','p＝0.001，即千分之一'),T('期望值','（1－p）×100＋p×8000000＝8099.9ns')],[P('先统一单位。八毫秒是八百万纳秒。本题把缺页的一次总耗时设为八毫秒，正常访问一百纳秒，缺页率千分之一。',[1,2],['毫秒、微秒、纳秒不能直接混加','总耗时定义已包含该次访问'],phase='latency',anchor='八毫秒是八百万纳秒'),P('按两条路径加权，得到八千零九十九点九纳秒，约八点一微秒。即使缺页率很小，外存代价仍会明显影响平均访问时间。若题目把八毫秒写成额外调页时间，或者把脏页写回概率单列，公式就要按新定义调整；不能把同一项重复算两次。遇到有效访问时间，先画所有可能路径，分别列代价与概率，再相加。题目没说的缓存命中、页表层数或写回次数，不要擅自补入。',[3],['先判断给的是总耗时还是附加耗时','概率与代价一一对应'],phase='expectation',anchor='按两条路径加权')],['缺页有效访问时间'],visual=G('latency'))
S(c,'页框分配、工作集与抖动',[T('局部与全局置换','候选来自本进程，或可来自其他进程'),T('工作集与抖动','近期常用页装不下，频繁换入换出'),T('写时复制','先共享只读映射，写入时再按需复制')],[P('局部置换主要从本进程分得的页框中选，全局置换可以按系统规则从更大范围选择。若活跃工作集需要的页面装不下，刚换出的页面很快又要读回，就可能发生抖动。此时处理器利用率低，不一定是任务太少；继续增加并发任务，反而可能使内存压力更重。',[1,2],['局部或全局决定候选范围','抖动时不能机械增加多道程序度'],phase='thrash',anchor='刚换出的页面很快又要读回'),P('写时复制是另一种常见优化：创建相关进程时，先共享某些只读映射，真正写入时再复制对应页，保持逻辑上的隔离。它不表示两个进程可以无条件互相改写私有数据，也不表示创建时永远不需要复制任何内容。题目涉及进程创建与页面共享时，把逻辑隔离和物理暂时共享分开。',[3],['共享映射要有保护与写入处理','写时复制保留进程隔离语义'],phase='cow',anchor='真正写入时再复制对应页')],['页框分配','工作集与抖动','写时复制'],visual=G('working_set'))
S(c,'LRU练习',[T('题设','3个空页框，访问序列1、2、3、1、4、2'),T('算法','采用LRU，命中也更新使用次序'),T('问题','缺页几次？访问4时淘汰谁？')],[P('暂停按LRU逐步填表。三个页框初始全空，依次访问一、二、三、一、四、二。请数缺页次数，并指出访问四时淘汰哪一个页。第四次访问一虽然命中，也必须更新最近使用关系；这一点会影响后面四和二的处理结果。',[1,2,3],['命中不增加缺页，但会改变LRU次序','每一步都写当前驻留页面'])],['虚拟内存练习'],kind='question')
S(c,'LRU练习答案',[T('前三次','1、2、3装入，各缺页一次'),T('访问1、4','1命中；4到达时淘汰最近最久未用的2'),T('最后访问2','2再缺页，共5次；不能只数替换')],[P('前三次缺页共三次；第四次访问一命中，此时最近最久没用的是二。访问四淘汰二，缺页数变四；最后又访问二，它已被换出，所以再缺一次，总共五次。若用FIFO，同一条短序列可能得到不同结果，因此不能把某次题目的优劣关系当成所有序列的固定规律。',[1,2,3],['访问4时应淘汰2','本题LRU缺页5次'])],['虚拟内存练习'],kind='answer')
c=C('文件、目录与文件系统')
S(c,'文件访问与逻辑块号',[T('文件视图','有名称、属性和内容；内容可按字节组织'),T('例题','块4KiB，字节偏移10000'),T('定位','逻辑块号2，块内偏移1808')],[P('文件让程序按名字和接口使用长期保存的数据，不必直接记住所有磁盘扇区。顺序访问沿当前位置读写，随机访问允许定位到指定偏移。以四KiB块为例，字节偏移一万除以四千零九十六，得到逻辑块号二、块内偏移一千八百零八。注意偏移从零开始。',[1,2],['逻辑块号先由文件内偏移计算','文件逻辑块不等于已经知道物理盘块']),P('接下来还需要按文件分配方式，把逻辑块号变成物理盘块号。文件的逻辑结构描述用户怎样组织内容，例如记录或字节流；物理结构描述这些内容在存储介质上怎样分配。不能因为文件是顺序访问，就断言它必须连续占据物理磁盘空间。访问方式和分配方式是两个维度。',[3],['先算文件内块号，再查物理分配','逻辑结构与物理结构不要混同'])],['文件访问与地址定位'])
S(c,'连续、链接与FAT分配',[T('连续分配','记录起始块和长度；随机定位方便'),T('隐式链接','每个数据块保存下一块位置'),T('FAT','把链接关系集中放到文件分配表')],[P('连续分配把文件放在相邻盘块，已知起始块就容易定位第几个逻辑块，但增长和外部碎片可能带来困难。隐式链接把下一块地址放在当前块里，扩展灵活，却不利于直接定位远处块：通常得沿链一步步走。图中有些块不相邻，文件仍能通过链接完整读出。',[1,2],['连续分配便于直接计算位置','隐式链接常需沿链查找'],phase='contiguous',anchor='放在相邻盘块'),P('FAT把下一块关系集中放在一张表中，可以缓存到内存，减少为了追踪链而读取每个数据块的代价。但它仍然是链关系，不会自动变成按逻辑块号直接索引的数据结构。分析一次访问需要几次外存读时，要说明FAT是否已在内存、哪些元数据已缓存，不能只背一个固定次数。',[3],['FAT集中保存链关系','I/O次数取决于元数据缓存假设'],phase='fat',anchor='集中放在一张表中')],['连续与链接分配','FAT'],visual=G('file_allocation'))
S(c,'索引分配与最大文件容量',[T('索引分配','索引项给出对应数据盘块号'),T('例题参数','块4KiB；块号4字节；每索引块1024项'),T('混合索引','12直接＋1单级＋1二级：数据块数12＋1024＋1024²')],[P('索引分配额外使用索引块保存数据块地址，便于按逻辑块号找对应项。四KiB的索引块、每个块号四字节，就能放一千零二十四个地址项。直接地址指数据块，单级间接地址先指索引块，二级则还要多一层。先把指针层次画清，不能把每一层都当成最终数据。',[1,2],['索引项数量＝索引块大小÷块号大小','每深入一层，寻址范围再乘项数'],phase='direct',anchor='直接地址指数据块'),P('本例混合索引有十二个直接项、一个单级项和一个二级项，最多寻址的数据块数是十二，加一千零二十四，再加一千零二十四的平方。最后乘数据块大小才是容量。用于保存索引的元数据块不属于用户文件的数据容量，题目问占用磁盘总块数时，才另外统计它们。',[3],['最大数据容量与磁盘总占用不同','最后记得乘数据块大小'],phase='indirect',anchor='一个单级项和一个二级项')],['索引分配','混合索引容量'],visual=G('file_index'))
S(c,'目录、FCB与索引节点',[T('目录作用','把文件名映射到相应管理信息'),T('FCB与索引节点','记录类型、长度、权限和数据定位信息等'),T('路径查找','逐级解析目录，而不是把路径当物理地址')],[P('目录让人通过名字查找文件，文件控制块记录文件的管理信息。采用索引节点的设计中，目录项常保留名字与索引节点编号等信息，再由索引节点记录属性和数据位置。目录项、索引节点和数据块是不同对象，不能把一个文件名直接当成完整文件内容。',[1,2],['文件名与文件本体分开','索引节点不等于一个用户数据块'],phase='directory',anchor='目录项常保留名字'),P('查找斜杠course、斜杠os、斜杠note这样的路径，要从相应起点逐级解析。绝对路径从根开始，相对路径从当前工作目录等给定起点开始。若题目计算访问次数，要明确根目录信息、目录块和索引节点哪些已缓存。挂载点还可能让某一级路径进入另一文件系统，而不是把磁盘上的全部格式变成同一种。',[3],['相对路径依赖当前起点','缓存条件会改变外存访问次数'],phase='path',anchor='逐级解析')],['目录与FCB','索引节点与路径'],visual=G('directory'))
S(c,'打开文件表与读写位置',[T('文件描述符','进程通过它引用已打开的文件'),T('打开文件状态','记录访问方式、当前位置等运行信息'),T('区分情况','重新open与继承同一打开状态，偏移关系可能不同')],[P('打开文件后，进程通常通过一个描述符继续读写，不需要每次重新解析完整路径。进程的描述符表可以指向系统中的打开文件状态，其中包含当前位置等信息。文件在磁盘上的属性、内核中的打开状态、进程手里的描述符，是不同层次；不要把当前读到哪里永久写进唯一的文件名里。',[1,2],['描述符是引用入口','当前位置属于具体打开状态'],phase='open',anchor='进程的描述符表'),P('在常见POSIX语义中，分别调用两次open可以得到独立的打开状态和文件偏移；通过fork继承的描述符则可能共享同一打开文件状态。因此一个参与者读完后，另一个读到哪里，必须看它们是否共享偏移。不能因为都访问同名文件，就断言读写位置一定相同，也不能断言一定独立。',[3],['同一文件不等于同一打开状态','偏移共享要结合open、继承等具体语义'],phase='offset',anchor='共享同一打开文件状态')],['打开文件表','文件偏移'],visual=G('open_files'))
S(c,'硬链接、软链接与保护',[T('硬链接','多个名字引用同一文件对象'),T('符号链接','保存目标路径，解析时再追踪'),T('权限与删除','删除一个名字不一定立即释放文件数据')],[P('硬链接给同一个文件对象增加名字；符号链接保存的是通向目标的路径。删除原来的一个名字，只要还有其他硬链接，文件对象仍可被访问；符号链接则可能因目标路径失效而成为悬空链接。常见文件系统中，硬链接一般不能跨文件系统，符号链接可以跨越路径对应的边界，仍以具体系统规则为准。',[1,2],['硬链接引用对象，软链接保存路径','删除某个名字与删除对象不同']),P('还要区分名字引用和打开引用。在常见POSIX系统中，名字全部删除后，若仍有进程保持打开引用，数据也可能暂时保留到最后关闭。权限检查则决定谁能读、写或执行，不能把共享误解为无条件公开。目录的遍历权限与普通文件执行权限含义也不同，做题按对象类型理解。',[3],['打开引用也可能延长对象存续','权限含义要结合文件与目录'])],['链接与共享','文件保护'])
S(c,'VFS、挂载与一致性',[T('VFS','为不同文件系统提供统一操作接口'),T('挂载','把文件系统接入目录树的某个位置'),T('一致性','缓存、写回、日志与恢复需分别分析')],[P('虚拟文件系统把打开、读取、关闭等操作组织成统一接口，下面仍可以连接不同的具体文件系统。挂载把某个文件系统接到目录树中，路径查找经过挂载点时进入对应实现。统一接口不表示所有介质布局相同，也不表示所有文件系统都具有完全相同的功能和限制。',[1,2],['VFS统一接口，不统一全部盘上格式','挂载改变路径树的连接关系']),P('写操作返回时，数据可能还在缓存中，并不必然已落到持久介质。日志帮助系统在故障后恢复一致性，但元数据日志不一定保证所有最新用户数据都已保存。题目问断电后有什么保证，要读清写回与同步条件，不把平时读起来正确当成崩溃后一定完整。文件系统一致性和业务数据完整性也不完全相同。',[3],['写入缓存与持久化不是同一步','日志保证范围取决于具体模式'])],['VFS与挂载','文件系统一致性'])
S(c,'索引容量练习',[T('题设','块大小1KiB，块号占4字节'),T('结构','4个直接地址＋1个单级间接地址'),T('问题','最大数据容量是多少？索引块计入数据容量吗？')],[P('暂停计算。一个简化索引节点有四个直接地址和一个单级间接地址，块大小一KiB，每个块号四字节。先求一个索引块能存多少项，再加上直接寻址的数据块，最后换算最大数据容量。题目问的是用户数据容量，不是索引节点和索引块合计占了多少磁盘空间。',[1,2,3],['先算每块地址项数','元数据块不计入用户数据容量'])],['文件系统练习'],kind='question')
S(c,'索引容量练习答案',[T('地址项数','1024／4＝256'),T('数据块数','4＋256＝260'),T('最大数据容量','260×1KiB＝260KiB，索引块另计元数据开销')],[P('一个索引块可存二百五十六个块号，加上四个直接地址，共可寻址二百六十个数据块，最大数据容量二百六十KiB。这个上限不把索引块自身算作用户数据。若题目另问文件装满时总共占用多少块，还要加一个单级索引块，并按题设考虑索引节点所在位置等其他管理开销。',[1,2,3],['本题答案260KiB','数据容量与总存储开销分开统计'])],['文件系统练习'],kind='answer')

